if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); if(isset($_POST['delete'])){db()->prepare('DELETE FROM accounts WHERE id=?')->execute([$a['id']]);unset($_SESSION['account_id']);header('Location: login.php');exit;} if(isset($_POST['save'])){db()->prepare('UPDATE accounts SET name=?,email=?,imap_host=?,imap_port=?,smtp_host=?,smtp_port=?,imap_security=?,smtp_security=? WHERE id=?')->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['imap_host']),(int)$_POST['imap_port'],trim($_POST['smtp_host']),(int)$_POST['smtp_port'],$_POST['imap_security'],$_POST['smtp_security'],$a['id']]);$notice='Instellingen opgeslagen.';$a=account();}}
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instellingen - tfwbmail</title><link rel="icon" href="assets/logo.svg"><link rel="stylesheet" href="assets/style.css"></head><body class="login-page"><form class="login-card settings-card" method="post"><a href="index.php">← Terug naar inbox</a><h1>Accountinstellingen</h1><?php if($notice):?><div class="success"><?=h($notice)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Naam<input name="name" value="<?=h($a['name'])?>"></label><label>E-mailadres<input name="email" type="email" value="<?=h($a['email'])?>"></label><div class="two"><label>IMAP-server<input name="imap_host" value="<?=h($a['imap_host'])?>"></label><label>IMAP-poort<input name="imap_port" type="number" value="<?=h($a['imap_port'])?>"></label></div><div class="two"><label>SMTP-server<input name="smtp_host" value="<?=h($a['smtp_host'])?>"></label><label>SMTP-poort<input name="smtp_port" type="number" value="<?=h($a['smtp_port'])?>"></label></div><div class="two"><label>IMAP-beveiliging<select name="imap_security"><option value="ssl" <?=$a['imap_security']==='ssl'?'selected':''?>>SSL/TLS</option><option value="tls" <?=$a['imap_security']==='tls'?'selected':''?>>STARTTLS</option></select></label><label>SMTP-beveiliging<select name="smtp_security"><option value="ssl" <?=$a['smtp_security']==='ssl'?'selected':''?>>SSL/TLS</option><option value="tls" <?=$a['smtp_security']==='tls'?'selected':''?>>STARTTLS</option></select></label></div><button class="primary full" name="save">Opslaan</button><button class="danger full" name="delete" value="1" onclick="return confirm('Account verwijderen?')">Account verwijderen</button></form></body></html>